const request = $input.first().json;
return {
  json: {
    authorization: request.headers?.authorization || '',
    required_roles: ["admin", "c_level", "manager"],
    required_capability: "can_evaluate",
    request,
  },
};

const guard = $('Run Auth Guard').first().json;
if (!guard.ok) {
  return {
    json: {
      http_status: guard.status,
      body: { success: false, error: guard.code, message: guard.message },
    },
  };
}
const body = guard.request.body || guard.request;
const actorId = Number(guard.identity.id);
const role = String(guard.identity.role || '');
const subjectId = parseInt(body.subject_id, 10);
const criteriaId = parseInt(body.criteria_id, 10);
const correctionScore = parseInt(body.correction_score, 10);
if (!Number.isFinite(subjectId) || !Number.isFinite(criteriaId) || !Number.isFinite(correctionScore)) {
  return {
    json: {
      http_status: 422,
      body: {
        success: false,
        error: 'INVALID_BODY',
        message: 'Укажите сотрудника, критерий и корректирующую оценку',
      },
    },
  };
}
if (correctionScore < 1 || correctionScore > 10) {
  return {
    json: {
      http_status: 422,
      body: {
        success: false,
        error: 'GRADE_OUT_OF_RANGE',
        message: 'Корректирующая оценка должна быть от 1 до 10',
      },
    },
  };
}
return {
  json: {
    ok: true,
    actor_id: actorId,
    role,
    subject_id: subjectId,
    criteria_id: criteriaId,
    correction_score: correctionScore,
    sql: `
      SELECT
        s.id AS subject_id,
        s.manager_id AS subject_manager_id,
        sm.manager_id AS skip_level_id,
        s.is_project_participant AS subject_is_project,
        COALESCE((
          SELECT json_agg(c.id)
          FROM performance_db.criteria c
          WHERE c.target_audience = 'project_participants'
        ), '[]'::json) AS project_criteria_ids,
        (
          SELECT p.id
          FROM performance_db.evaluation_periods p
          WHERE p.is_active = true AND p.status = 'active'
            AND p.evaluation_started_at IS NOT NULL
            AND p.period_type <> 'annual'
            AND NOT EXISTS (SELECT 1 FROM performance_db.evaluation_periods child
                            WHERE child.parent_period_id = p.id)
          LIMIT 1
        ) AS period_id
      FROM performance_db.users s
      LEFT JOIN performance_db.users sm ON sm.id = s.manager_id
      WHERE s.id = ${subjectId}
    `,
  },
};

const prev = $('Validate Input').first().json;
if (prev.http_status) {
  return { json: prev };
}
const row = $input.all().map(item => item.json).find(item => item.subject_id !== undefined);
if (!row) {
  return {
    json: {
      http_status: 404,
      body: { success: false, error: 'NOT_FOUND', message: 'Сотрудник не найден' },
    },
  };
}
// ── Applicability, classification dimension only (D-0822-3) ─────────────────
// A project_participants criterion applies to a subject iff the subject is
// CURRENTLY a project participant — the same shared predicate as submit,
// additive, update and self-review. Corrections live inside the cell, so a
// correction for an inapplicable criterion must be refused the same way.
// Checked before the period gate: the refusal is non-mutating either way,
// and the deployed rule stays provable on live while no campaign runs.
const parseIdList = (raw) => {
  let value = raw;
  if (typeof value === 'string') {
    try { value = JSON.parse(value); } catch { value = []; }
  }
  return Array.isArray(value) ? value.map(Number) : [];
};
const projectCriteriaIds = parseIdList(row.project_criteria_ids);
const subjectIsProject = row.subject_is_project === true || row.subject_is_project === 't';
if (!subjectIsProject && projectCriteriaIds.includes(Number(prev.criteria_id))) {
  return {
    json: {
      http_status: 422,
      body: {
        success: false,
        error: 'CRITERIA_NOT_APPLICABLE',
        message: `Критерий ${prev.criteria_id} — проектный, а сотрудник сейчас не участник проекта`,
      },
    },
  };
}
if (!row.period_id) {
  return {
    json: {
      http_status: 409,
      body: {
        success: false,
        error: 'NO_ACTIVE_PERIOD',
        message: 'Корректировка доступна только в идущем периоде оценки (период активирован и оценка запущена)',
      },
    },
  };
}
let correctionLevel = 'none';
if (prev.role === 'admin' || prev.role === 'c_level') {
  correctionLevel = 'c_level';
} else if (Number(row.skip_level_id) === Number(prev.actor_id)) {
  correctionLevel = 'mid_level';
}
if (correctionLevel === 'none') {
  return {
    json: {
      http_status: 403,
      body: {
        success: false,
        error: 'OWNERSHIP_FORBIDDEN',
        message: 'Корректировка доступна руководителю руководителя, администратору или C-level',
      },
    },
  };
}
return {
  json: {
    ok: true,
    actor_id: prev.actor_id,
    subject_id: prev.subject_id,
    criteria_id: prev.criteria_id,
    correction_score: prev.correction_score,
    correction_level: correctionLevel,
    period_id: Number(row.period_id),
    sql: `
      INSERT INTO performance_db.score_corrections
        (subject_id, evaluator_id, criteria_id, correction_score, correction_level, period_id, updated_at)
      VALUES
        (${prev.subject_id}, ${prev.actor_id}, ${prev.criteria_id}, ${prev.correction_score}, '${correctionLevel}', ${Number(row.period_id)}, NOW())
      ON CONFLICT (subject_id, criteria_id, correction_level, period_id)
      DO UPDATE SET
        correction_score = EXCLUDED.correction_score,
        evaluator_id = EXCLUDED.evaluator_id,
        updated_at = NOW()
      RETURNING id, subject_id, criteria_id, correction_score, correction_level, period_id
    `,
  },
};

const prev = $('Decide Level').first().json;
if (prev.http_status) {
  return { json: prev };
}
const row = $input.all().map(item => item.json).find(item => item.id !== undefined);
if (!row) {
  return {
    json: {
      http_status: 500,
      body: { success: false, error: 'WRITE_FAILED', message: 'Score correction was not stored' },
    },
  };
}
return {
  json: {
    http_status: 200,
    body: {
      success: true,
      message: 'Score correction saved successfully',
      data: {
        id: row.id,
        subject_id: row.subject_id,
        criteria_id: row.criteria_id,
        correction_score: row.correction_score,
        correction_level: row.correction_level,
      },
    },
  },
};
